mapper.select:
SELECT 
FROM data_subject_request
WHERE org_id = #{orgId} AND id = #{requestId}

SELECT 
FROM data_subject_request
WHERE org_id = #{orgId}

  AND status = #{status}

ORDER BY received_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT EXISTS(
  SELECT 1
  FROM workspace w
  JOIN person p ON p.workspace_id = w.id
  WHERE w.id = #{workspaceId} AND w.org_id = #{orgId} AND p.id = #{personId}
)

SELECT t.id, t.workspace_id, t.name, t.color
FROM person p
JOIN workspace subject_workspace
  ON subject_workspace.id = p.workspace_id AND subject_workspace.org_id = #{orgId}
JOIN person_tag pt ON pt.person_id = p.id
JOIN tag t ON t.id = pt.tag_id
JOIN workspace tag_workspace
  ON tag_workspace.id = t.workspace_id AND tag_workspace.org_id = #{orgId}
WHERE p.workspace_id = #{workspaceId} AND p.id = #{personId}
ORDER BY t.name, t.id

SELECT a.id, a.workspace_id, a.type, a.subject, a.notes, a.person_id, a.deal_id,
       a.created_by_id, a.timestamp
FROM person p
JOIN workspace subject_workspace
  ON subject_workspace.id = p.workspace_id AND subject_workspace.org_id = #{orgId}
JOIN activity a ON a.person_id = p.id
JOIN workspace activity_workspace
  ON activity_workspace.id = a.workspace_id AND activity_workspace.org_id = #{orgId}
WHERE p.workspace_id = #{workspaceId} AND p.id = #{personId}
ORDER BY a.timestamp DESC, a.id DESC

SELECT n.id, n.workspace_id, n.content, n.title, n.author_id, n.person_id, n.deal_id,
       n.visibility, n.created_at, n.updated_at
FROM person p
JOIN workspace subject_workspace
  ON subject_workspace.id = p.workspace_id AND subject_workspace.org_id = #{orgId}
JOIN note n ON n.person_id = p.id
JOIN workspace note_workspace
  ON note_workspace.id = n.workspace_id AND note_workspace.org_id = #{orgId}
WHERE p.workspace_id = #{workspaceId} AND p.id = #{personId}
ORDER BY n.created_at DESC, n.id DESC

SELECT t.id, t.workspace_id, t.description, t.completed, t.status, t.position, t.due_date,
       t.assigned_to_id, t.person_id, t.deal_id, t.created_at, t.updated_at
FROM person p
JOIN workspace subject_workspace
  ON subject_workspace.id = p.workspace_id AND subject_workspace.org_id = #{orgId}
JOIN task t ON t.person_id = p.id
JOIN workspace task_workspace
  ON task_workspace.id = t.workspace_id AND task_workspace.org_id = #{orgId}
WHERE p.workspace_id = #{workspaceId} AND p.id = #{personId}
ORDER BY t.created_at DESC, t.id DESC

SELECT a.id, a.workspace_id, a.file_name, a.content_type, a.size, a.uploaded_by_id, a.created_at
FROM person p
JOIN workspace subject_workspace
  ON subject_workspace.id = p.workspace_id AND subject_workspace.org_id = #{orgId}
JOIN attachment a ON a.entity_type = 'person' AND a.entity_id = p.id
JOIN workspace attachment_workspace
  ON attachment_workspace.id = a.workspace_id AND attachment_workspace.org_id = #{orgId}
WHERE p.workspace_id = #{workspaceId} AND p.id = #{personId}
ORDER BY a.created_at DESC, a.id DESC

SELECT e.id, e.workspace_id, e.person_id, e.company_id, e.company_name, e.title,
       e.started_at, e.ended_at, e.created_at
FROM person p
JOIN workspace subject_workspace
  ON subject_workspace.id = p.workspace_id AND subject_workspace.org_id = #{orgId}
JOIN person_employment e ON e.person_id = p.id
JOIN workspace employment_workspace
  ON employment_workspace.id = e.workspace_id AND employment_workspace.org_id = #{orgId}
WHERE p.workspace_id = #{workspaceId} AND p.id = #{personId}
ORDER BY e.started_at DESC, e.created_at DESC, e.id DESC
